-- Island 4: Control Flow & Conditional Logic
-- Express/MySQL schema migration. Safe to re-run.
USE codequest;

INSERT INTO lesson_modules (id, title, description, color, order_index, is_active)
VALUES (4, 'Control Flow and Conditional Logic', 'Choose actions with if, else if, else, and logical operators.', '#EF4444', 4, TRUE)
ON DUPLICATE KEY UPDATE
  title = VALUES(title),
  description = VALUES(description),
  color = VALUES(color),
  order_index = VALUES(order_index),
  is_active = TRUE;

-- Update existing module 4 lessons by their relative order.
UPDATE lessons SET level_label='Level 1', track='JAVA CONTROL FLOW', title='The Pressure Plate', briefing='Pip must step on a weight plate. The gate opens only if the measured weight is sufficient, so he checks one condition before moving forward.', hint='Use if to run openGate only when weight is at least 10.', goal='Use a single if statement to open the gate when the weight is sufficient.', xp_reward=40, order_index=1 WHERE module_id=4 AND order_index=1;
UPDATE lessons SET level_label='Level 2', track='JAVA CONTROL FLOW', title='The Fork in the Path', briefing='Pip reaches a split bridge. If the left path is clear he takes it; otherwise, he crosses the right rope bridge.', hint='Use else for the path that runs when the first condition is false.', goal='Choose between the left and right bridge with if and else.', xp_reward=45, order_index=2 WHERE module_id=4 AND order_index=2;
UPDATE lessons SET level_label='Level 3', track='JAVA CONTROL FLOW', title='Health Inspection', briefing='Before entering toxic mist, Pip checks his shield points. Strong protection lets him cross; otherwise, he drinks a potion first.', hint='Compare shieldPoints with 50 inside the condition.', goal='Branch on a numeric shield threshold before entering the mist.', xp_reward=50, order_index=3 WHERE module_id=4 AND order_index=3;
UPDATE lessons SET level_label='Level 4', track='JAVA CONTROL FLOW', title='Runic Key Match', briefing='A magic vault compares the rune on Pip''s key with the door lock. In Java, String values must be compared with equals before the vault opens.', hint='Call equals on keyType instead of using == for String content.', goal='Use String.equals to accept the Gold key and reject other keys.', xp_reward=55, order_index=4 WHERE module_id=4 AND order_index=4;
UPDATE lessons SET level_label='Level 5', track='JAVA CONTROL FLOW', title='Elemental Guard', briefing='An elemental barrier changes between Fire, Water, and Earth. Pip checks each element in order and casts the matching counter-spell, with a shield as the final fallback.', hint='Chain else if branches between the first if and the final else.', goal='Select a counter-spell with a three-way conditional chain.', xp_reward=60, order_index=5 WHERE module_id=4 AND order_index=5;
UPDATE lessons SET level_label='Level 6', track='JAVA CONTROL FLOW', title='Double Lock Sentinel', briefing='A heavy drawbridge has two powered levers. Pip can lower it only when both side levers are on at the same time.', hint='The && operator is true only when leverA and leverB are both true.', goal='Require two conditions together with logical AND.', xp_reward=60, order_index=6 WHERE module_id=4 AND order_index=6;
UPDATE lessons SET level_label='Level 7', track='JAVA CONTROL FLOW', title='Emergency Exit', briefing='Pip finds an escape door. A master key card or knowledge of the secret phrase is enough, so either successful condition can unlock the exit.', hint='The || operator succeeds when at least one condition is true.', goal='Open the escape door with logical OR.', xp_reward=65, order_index=7 WHERE module_id=4 AND order_index=7;
UPDATE lessons SET level_label='Level 8', track='JAVA CONTROL FLOW', title='Guard Duty', briefing='At a checkpoint, Pip first checks whether the guard is awake. Only an awake guard leads to the second check for a valid pass.', hint='Place the pass check inside the guard-awake if block.', goal='Use a nested if to protect the checkpoint entry.', xp_reward=70, order_index=8 WHERE module_id=4 AND order_index=8;
UPDATE lessons SET level_label='Level 9', track='JAVA CONTROL FLOW', title='The Trap Evaluator', briefing='Pip crosses a trap grid where a tile is safe only when its lamp is off and his energy remains below 100.', hint='Combine !isLit with energyLevel < 100 using &&.', goal='Evaluate negation and a numeric condition together.', xp_reward=75, order_index=9 WHERE module_id=4 AND order_index=9;
UPDATE lessons SET level_label='Level 10', track='JAVA CONTROL FLOW', title='Control Flow Boss Arena', briefing='The Logic Warden shifts phases based on health, rage, and element. Pip must combine branches, String equality, and logical operators to choose the correct combat counter-action.', hint='Check the boss conditions from most specific to the final fallback action.', goal='Synthesize Java control flow to defeat the Logic Warden.', xp_reward=100, order_index=10 WHERE module_id=4 AND order_index=10;

