INSERT INTO guided_steps (lesson_id, step_order, prompt, correct_snippet, distractor_1, distractor_2, distractor_3) VALUES
(@level1_id,1,'Pip must step on the pressure plate. Which if statement opens the gate only when weight is sufficient?','if (weight >= 10) { openGate(); }','if (weight > 10) { openGate(); }','if (weight = 10) { openGate(); }','if (weight >= 10) openGate();'),
(@level2_id,1,'Pip reaches a split bridge. Which if-else branch chooses the clear left path or the right rope bridge?','if (isLeftPathClear) { moveLeft(); } else { moveRight(); }','if (isLeftPathClear) { moveRight(); } else { moveLeft(); }','if (isLeftPathClear) moveLeft();','else (isLeftPathClear) { moveRight(); }'),
(@level3_id,1,'Pip checks his shield before toxic mist. Which branch crosses when shieldPoints is above 50 and drinks a potion otherwise?','if (shieldPoints > 50) { crossMist(); } else { drinkPotion(); }','if (shieldPoints >= 50) { drinkPotion(); } else { crossMist(); }','if (shieldPoints < 50) { crossMist(); }','if (shieldPoints = 50) { drinkPotion(); }'),
(@level4_id,1,'Which Java condition matches Pip''s Gold rune with String.equals before unlocking the vault?','if (keyType.equals("Gold")) { unlockVault(); } else { rejectKey(); }','if (keyType == "Gold") { unlockVault(); }','if (keyType.equals(Gold)) { unlockVault(); }','if (keyType = "Gold") { unlockVault(); }'),
(@level5_id,1,'Which chain selects the counter-spell for Fire, Water, or Earth?','if (element.equals("Fire")) { castWater(); } else if (element.equals("Water")) { castLightning(); } else { castShield(); }','if (element == "Fire") { castWater(); } else { castShield(); }','else if (element.equals("Water")) { castLightning(); }','if (element.equals("Fire")) castWater(); else castLightning();'),
(@level6_id,1,'Which condition lowers the drawbridge only when both powered levers are on?','if (leverA && leverB) { lowerBridge(); }','if (leverA || leverB) { lowerBridge(); }','if (leverA & leverB) { lowerBridge(); }','if (leverA && !leverB) { lowerBridge(); }'),
(@level7_id,1,'Which condition opens the emergency exit when either the key card or passcode is available?','if (hasMasterKey || knowsPasscode) { escape(); }','if (hasMasterKey && knowsPasscode) { escape(); }','if (hasMasterKey | knowsPasscode) { escape(); }','if (hasMasterKey || !knowsPasscode) { escape(); }'),
(@level8_id,1,'Which nested if checks that the guard is awake before checking Pip''s pass?','if (isGuardAwake) { if (hasPass) { passCheckpoint(); } }','if (hasPass) { if (isGuardAwake) { passCheckpoint(); } }','if (isGuardAwake && hasPass) { passCheckpoint(); }','if (isGuardAwake) { passCheckpoint(); }'),
(@level9_id,1,'Which condition steps safely only when the tile is unlit and energy is below 100?','if (!isLit && energyLevel < 100) { stepSafely(); }','if (isLit && energyLevel < 100) { stepSafely(); }','if (!isLit || energyLevel < 100) { stepSafely(); }','if (isLit && energyLevel > 100) { stepSafely(); }'),
(@level10_id,1,'Which control-flow block evaluates boss health, rage, and element to choose the combat counter?','if (bossHealth < 30 && isEnraged) { castShield(); } else if (element.equals("Fire")) { castWater(); } else { strike(); }','if (bossHealth < 30 || isEnraged) { castShield(); }','if (element == "Fire" && bossHealth > 30) { castWater(); }','if (bossHealth = 30) { strike(); }');
